def first_index(a, target):
    """Return the index of the FIRST occurrence of target in the sorted list a, or -1 if absent."""
    lo, hi = 0, len(a) - 1
    result = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if a[mid] == target:
            result = mid
            hi = mid - 1
        elif a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return result

